(function (root) {
"use strict";
async function loadBagsAndItems(client, userId) {
const { data: bagsData, error: bagsErr } = await client
.from("bags")
.select("id, name")
.eq("user_id", userId)
.order("created_at", { ascending: true });
if (bagsErr) return { error: bagsErr };
const { data: itemsData, error: itemsErr } = await client
.from("items")
.select("*")
.eq("user_id", userId)
.order("added_at", { ascending: false });
if (itemsErr) return { error: itemsErr };
const bags = {};
const order = [];
(bagsData || []).forEach((bag) => {
bags[bag.id] = { id: bag.id, name: bag.name, items: [] };
order.push(bag.id);
});
(itemsData || []).forEach((item) => {
const bag = bags[item.bag_id];
if (!bag) return;
bag.items.push({
id: item.id,
title: item.title,
price: item.price,
originalPrice: item.original_price,
size: item.size,
site: item.site,
image: item.image,
url: item.url,
addedAt: item.added_at
});
});
return { data: { order, bags } };
}
async function createBag(client, userId, name) {
const { data, error } = await client
.from("bags")
.insert({ user_id: userId, name })
.select()
.single();
if (error) return { error };
return { data: { id: data.id, name: data.name, items: [] } };
}
async function deleteBag(client, bagId) {
const { error } = await client.from("bags").delete().eq("id", bagId);
if (error) return { error };
return { data: true };
}
async function deleteItem(client, itemId) {
const { error } = await client.from("items").delete().eq("id", itemId);
if (error) return { error };
return { data: true };
}
function parsePriceNumber(str) {
if (!str) return null;
const match = String(str).replace(/,/g, "").match(/\d+(\.\d+)?/);
return match ? parseFloat(match[0]) : null;
}
function formatPriceDropLabel(item) {
const was = parsePriceNumber(item.originalPrice);
const now = parsePriceNumber(item.price);
if (was === null || now === null || now >= was) return null;
return `was ${item.originalPrice}`;
}
function relativeDate(iso) {
if (!iso) return "";
const then = new Date(iso);
const diffDays = Math.floor((Date.now() - then.getTime()) / (1000 * 60 * 60 * 24));
if (diffDays <= 0) return "Today";
if (diffDays === 1) return "Yesterday";
if (diffDays < 7) return `${diffDays} days ago`;
return then.toLocaleDateString(undefined, { day: "numeric", month: "short" });
}
// Basic HTML-escaping for safely inserting free text (item titles, bag
// names — anything that ultimately came from a product page or a person's
// own typing) into innerHTML. DOM-based like popup.js's version, so it
// only works where `document` exists (any normal web/extension page).
function escapeHtml(str) {
const d = document.createElement("div");
d.innerText = str == null ? "" : String(str);
return d.innerHTML;
}
const BaggleData = {
loadBagsAndItems,
createBag,
deleteBag,
deleteItem,
parsePriceNumber,
formatPriceDropLabel,
relativeDate,
escapeHtml
};
if (typeof module !== "undefined" && module.exports) {
module.exports = BaggleData;
} else {
root.BaggleData = BaggleData;
}
})(typeof globalThis !== "undefined" ? globalThis : this);
