// Baggle — web dashboard
//
// Real account data: signs in with the same Supabase project/account as
// the browser extension, then reads and writes the same `bags`/`items`
// tables via shared/baggle-data.js. No separate backend — Supabase's Row
// Level Security is what keeps this safe to run as a plain static page
// (see shared/supabase-config.js for why the key embedded here is safe to
// ship).
const dashboardSupabase = supabase.createClient(
globalThis.BAGGLE_SUPABASE_URL,
globalThis.BAGGLE_SUPABASE_ANON_KEY,
{
auth: {
storageKey: "baggle_dashboard_session_v1",
autoRefreshToken: true,
persistSession: true,
detectSessionInUrl: false
}
}
);
let currentUser = null;
let state = { order: [], bags: {} };
let authMode = "login"; // "login" | "signup"
let openBagId = null;
// ---------- element refs ----------
const viewAuth = document.getElementById("view-auth");
const dashShell = document.getElementById("dashShell");
const viewHome = document.getElementById("view-home");
const viewBag = document.getElementById("view-bag");
const authEmailInput = document.getElementById("authEmail");
const authPasswordInput = document.getElementById("authPassword");
const authErrorEl = document.getElementById("authError");
const authNoticeEl = document.getElementById("authNotice");
const authSubmitBtn = document.getElementById("authSubmitBtn");
const authSwitchText = document.getElementById("authSwitchText");
const authSwitchBtn = document.getElementById("authSwitchBtn");
const forgotPasswordRow = document.getElementById("forgotPasswordRow");
const forgotPasswordBtn = document.getElementById("forgotPasswordBtn");
const avatarChip = document.getElementById("avatarChip");
const totalCountPill = document.getElementById("totalCountPill");
const bagsGrid = document.getElementById("bagsGrid");
const bagTitle = document.getElementById("bagTitle");
const bagCountPill = document.getElementById("bagCountPill");
const itemsGrid = document.getElementById("itemsGrid");
const backBtn = document.getElementById("backBtn");
const deleteBagBtn = document.getElementById("deleteBagBtn");
const modalBackdrop = document.getElementById("modalBackdrop");
const newBagNameInput = document.getElementById("newBagNameInput");
const modalError = document.getElementById("modalError");
const modalCancelBtn = document.getElementById("modalCancelBtn");
const modalCreateBtn = document.getElementById("modalCreateBtn");
const sidebarCreateBagBtn = document.getElementById("sidebarCreateBagBtn");
const logoutBtn = document.getElementById("logoutBtn");
const toastEl = document.getElementById("toast");
// ---------- small helpers ----------
function flashToast(message) {
toastEl.textContent = message;
toastEl.classList.add("show");
setTimeout(() => toastEl.classList.remove("show"), 2600);
}
function initialsFor(email) {
if (!email) return "?";
const name = email.split("@")[0];
return name.slice(0, 2).toUpperCase();
}
// ---------- auth ----------
function setAuthMode(mode) {
authMode = mode;
authErrorEl.textContent = "";
authNoticeEl.textContent = "";
if (mode === "signup") {
authSubmitBtn.textContent = "Sign up";
authPasswordInput.setAttribute("autocomplete", "new-password");
authSwitchText.textContent = "Already have an account?";
authSwitchBtn.textContent = "Log in";
forgotPasswordRow.hidden = true;
} else {
authSubmitBtn.textContent = "Log in";
authPasswordInput.setAttribute("autocomplete", "current-password");
authSwitchText.textContent = "Don't have an account yet?";
authSwitchBtn.textContent = "Sign up";
forgotPasswordRow.hidden = false;
}
}
authSwitchBtn.addEventListener("click", () => {
setAuthMode(authMode === "login" ? "signup" : "login");
});
authPasswordInput.addEventListener("keydown", (e) => {
if (e.key === "Enter") authSubmitBtn.click();
});
authSubmitBtn.addEventListener("click", async () => {
const email = authEmailInput.value.trim();
const password = authPasswordInput.value;
authErrorEl.textContent = "";
authNoticeEl.textContent = "";
if (!email || !password) {
authErrorEl.textContent = "Enter an email and password.";
return;
}
if (password.length < 6) {
authErrorEl.textContent = "Password must be at least 6 characters.";
return;
}
authSubmitBtn.disabled = true;
const originalLabel = authSubmitBtn.textContent;
authSubmitBtn.textContent = authMode === "signup" ? "Signing up…" : "Logging in…";
try {
if (authMode === "signup") {
const { data, error } = await dashboardSupabase.auth.signUp({ email, password });
if (error) {
authErrorEl.textContent = error.message;
return;
}
if (data.session && data.user) {
await onAuthed(data.user);
} else {
// Same project, same setting as the extension: email confirmation
// is turned on, so there's no session until the link is clicked.
authNoticeEl.textContent = "Check your email to confirm your account, then log in below.";
setAuthMode("login");
authEmailInput.value = email;
}
} else {
const { data, error } = await dashboardSupabase.auth.signInWithPassword({ email, password });
if (error) {
authErrorEl.textContent = error.message;
return;
}
await onAuthed(data.user);
}
} catch (err) {
console.error(err);
authErrorEl.textContent = "Something went wrong reaching Baggle's servers. Check your connection and try again.";
} finally {
authSubmitBtn.disabled = false;
authSubmitBtn.textContent = originalLabel;
}
});
// Supabase emails a link that lands on reset-password.html (a separate
// page — see that file) where the person actually sets a new password.
// This just triggers that email; it doesn't need the password field at
// all, only whatever's currently typed into the email field above.
forgotPasswordBtn.addEventListener("click", async () => {
const email = authEmailInput.value.trim();
authErrorEl.textContent = "";
authNoticeEl.textContent = "";
if (!email) {
authErrorEl.textContent = 'Enter your email above first, then click "Forgot your password?" again.';
return;
}
forgotPasswordBtn.disabled = true;
const originalLabel = forgotPasswordBtn.textContent;
forgotPasswordBtn.textContent = "Sending…";
try {
const { error } = await dashboardSupabase.auth.resetPasswordForEmail(email, {
redirectTo: "https://baggle.net/dashboard/reset-password.html"
});
if (error) {
authErrorEl.textContent = error.message;
} else {
authNoticeEl.textContent = "Check your email for a link to reset your password.";
}
} catch (err) {
console.error(err);
authErrorEl.textContent = "Something went wrong reaching Baggle's servers. Check your connection and try again.";
} finally {
forgotPasswordBtn.disabled = false;
forgotPasswordBtn.textContent = originalLabel;
}
});
logoutBtn.addEventListener("click", async () => {
await dashboardSupabase.auth.signOut();
showLoggedOut();
});
function showLoggedOut() {
currentUser = null;
state = { order: [], bags: {} };
openBagId = null;
dashShell.hidden = true;
viewAuth.hidden = false;
authPasswordInput.value = "";
authErrorEl.textContent = "";
authNoticeEl.textContent = "";
setAuthMode("login");
}
async function onAuthed(user) {
currentUser = user;
avatarChip.textContent = initialsFor(user.email);
viewAuth.hidden = true;
dashShell.hidden = false;
const { data, error } = await BaggleData.loadBagsAndItems(dashboardSupabase, currentUser.id);
if (error) {
console.error("Failed to load bags/items", error);
flashToast("Couldn't load your bags — try refreshing.");
return;
}
state = data;
goHome();
}
dashboardSupabase.auth.onAuthStateChange((event) => {
if (event === "SIGNED_OUT") showLoggedOut();
});
dashboardSupabase.auth.getSession().then(({ data }) => {
if (data.session && data.session.user) {
onAuthed(data.session.user);
} else {
showLoggedOut();
}
});
// ---------- view switching ----------
function goHome() {
openBagId = null;
viewBag.classList.remove("active");
viewHome.classList.add("active");
renderHome();
window.scrollTo(0, 0);
}
function openBag(bagId) {
openBagId = bagId;
viewHome.classList.remove("active");
viewBag.classList.add("active");
renderBagDetail();
window.scrollTo(0, 0);
}
backBtn.addEventListener("click", goHome);
document.querySelectorAll(".side-btn[data-nav]").forEach((btn) => {
btn.addEventListener("click", () => {
const nav = btn.dataset.nav;
document.querySelectorAll(".side-btn[data-nav]").forEach((b) => b.classList.remove("active"));
if (nav === "home") {
btn.classList.add("active");
goHome();
} else if (nav === "notifications") {
btn.classList.add("active");
flashToast("Alerts are coming to the dashboard soon — check the extension's Notifications tab for now.");
}
});
});
// ---------- rendering: home (bags grid) ----------
const swatchIcon = '<svg viewBox="0 0 24 24"><path d="M8 4h8l2 3-3 2v11H9V9L6 7Z"/></svg>';
function bagCollageHtml(bag) {
const withImages = bag.items.filter((it) => it.image);
const main = withImages[0];
const secondA = bag.items[1];
const secondB = bag.items[2];
function tile(item, extraClass) {
if (item && item.image) {
return `<div class="tile ${extraClass}"><img src="${BaggleData.escapeHtml(item.image)}" alt=""></div>`;
}
return `<div class="tile ${extraClass}"><div class="swatch" style="background:var(--purple-soft)">${swatchIcon}</div></div>`;
}
if (bag.items.length === 0) {
return `<div class="tile tile-main"><div class="swatch" style="background:var(--cream)">${swatchIcon}</div></div>`;
}
return tile(main || bag.items[0], "tile-main") + tile(secondA, "") + tile(secondB, "");
}
function renderHome() {
const totalItems = state.order.reduce((sum, id) => sum + state.bags[id].items.length, 0);
totalCountPill.textContent = `${totalItems} item${totalItems === 1 ? "" : "s"} saved`;
if (state.order.length === 0) {
bagsGrid.innerHTML = `
<div class="bag-card new-bag" id="newBagTile">
<div class="new-bag-icon"><svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg></div>
<span>Create your first bag</span>
</div>`;
document.getElementById("newBagTile").addEventListener("click", openCreateBagModal);
return;
}
bagsGrid.innerHTML = state.order.map((bagId) => {
const bag = state.bags[bagId];
return `
<button class="bag-card" data-bag-id="${bagId}">
<div class="bag-collage">${bagCollageHtml(bag)}</div>
<div class="bag-meta">
<p class="bag-name">${BaggleData.escapeHtml(bag.name)}</p>
<p class="bag-count">${bag.items.length} item${bag.items.length === 1 ? "" : "s"}</p>
</div>
</button>`;
}).join("") + `
<button class="bag-card new-bag" id="newBagTile">
<div class="new-bag-icon"><svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg></div>
<span>Create new bag</span>
</button>`;
bagsGrid.querySelectorAll(".bag-card[data-bag-id]").forEach((card) => {
card.addEventListener("click", () => openBag(card.dataset.bagId));
});
document.getElementById("newBagTile").addEventListener("click", openCreateBagModal);
}
// ---------- rendering: bag detail (items grid) ----------
function renderBagDetail() {
const bag = state.bags[openBagId];
if (!bag) { goHome(); return; }
bagTitle.textContent = bag.name;
bagCountPill.textContent = `${bag.items.length} item${bag.items.length === 1 ? "" : "s"}`;
if (bag.items.length === 0) {
itemsGrid.innerHTML = `<div class="empty-items">Nothing saved here yet — save something from the extension and it'll show up here.</div>`;
return;
}
itemsGrid.innerHTML = bag.items.map((item) => {
const dropLabel = BaggleData.formatPriceDropLabel(item);
return `
<div class="item-card" data-item-id="${item.id}">
<div class="item-photo">${item.image ? `<img src="${BaggleData.escapeHtml(item.image)}" alt="${BaggleData.escapeHtml(item.title)}">` : `<div class="swatch" style="background:var(--cream)">${swatchIcon}</div>`}</div>
<div class="item-body">
<div class="item-store">${BaggleData.escapeHtml(item.site || "")}</div>
<div class="item-name">${BaggleData.escapeHtml(item.title)}</div>
<div class="item-price">${BaggleData.escapeHtml(item.price || "")}</div>
${dropLabel ? `<div class="item-drop">▾ ${BaggleData.escapeHtml(dropLabel)}</div>` : ""}
<div class="item-btns">
<button class="btn-pill remove-item-btn">Remove</button>
${item.url ? `<button class="btn-pill solid go-to-store-btn">Go to store</button>` : ""}
</div>
</div>
</div>`;
}).join("");
itemsGrid.querySelectorAll(".item-card").forEach((card) => {
const itemId = card.dataset.itemId;
const item = bag.items.find((i) => i.id === itemId);
card.querySelector(".remove-item-btn").addEventListener("click", async () => {
if (!confirm(`Remove "${item.title}" from ${bag.name}? This can't be undone.`)) return;
const { error } = await BaggleData.deleteItem(dashboardSupabase, itemId);
if (error) {
console.error("Failed to remove item", error);
flashToast("Couldn't remove that — try again.");
return;
}
bag.items = bag.items.filter((i) => i.id !== itemId);
renderBagDetail();
flashToast(`Removed "${item.title}"`);
});
const storeBtn = card.querySelector(".go-to-store-btn");
if (storeBtn) {
storeBtn.addEventListener("click", () => window.open(item.url, "_blank", "noopener"));
}
});
}
deleteBagBtn.addEventListener("click", async () => {
const bag = state.bags[openBagId];
if (!bag) return;
const itemCount = bag.items.length;
const warning = itemCount > 0
? `Delete "${bag.name}" and the ${itemCount} item${itemCount === 1 ? "" : "s"} in it? This can't be undone.`
: `Delete "${bag.name}"? This can't be undone.`;
if (!confirm(warning)) return;
deleteBagBtn.disabled = true;
const { error } = await BaggleData.deleteBag(dashboardSupabase, openBagId);
deleteBagBtn.disabled = false;
if (error) {
console.error("Failed to delete bag", error);
flashToast("Couldn't delete that bag — try again.");
return;
}
const name = bag.name;
state.order = state.order.filter((id) => id !== openBagId);
delete state.bags[openBagId];
goHome();
flashToast(`Deleted "${name}"`);
});
// ---------- create-bag modal ----------
function openCreateBagModal() {
newBagNameInput.value = "";
modalError.textContent = "";
modalBackdrop.hidden = false;
newBagNameInput.focus();
}
function closeCreateBagModal() {
modalBackdrop.hidden = true;
}
sidebarCreateBagBtn.addEventListener("click", openCreateBagModal);
modalCancelBtn.addEventListener("click", closeCreateBagModal);
modalBackdrop.addEventListener("click", (e) => {
if (e.target === modalBackdrop) closeCreateBagModal();
});
newBagNameInput.addEventListener("keydown", (e) => {
if (e.key === "Enter") modalCreateBtn.click();
if (e.key === "Escape") closeCreateBagModal();
});
modalCreateBtn.addEventListener("click", async () => {
const name = newBagNameInput.value.trim();
if (!name) {
modalError.textContent = "Give your bag a name.";
return;
}
modalCreateBtn.disabled = true;
const { data, error } = await BaggleData.createBag(dashboardSupabase, currentUser.id, name);
modalCreateBtn.disabled = false;
if (error) {
console.error("Failed to create bag", error);
modalError.textContent = "Couldn't create that bag — try again.";
return;
}
state.bags[data.id] = data;
state.order.push(data.id);
closeCreateBagModal();
renderHome();
flashToast(`Created "${data.name}"`);
});
